{
  "description": "The creature is shown in right-facing profile against a plain off-white background, standing on four short limbs. It has an elongated, tapered snout with a dark nostril at the tip and fine whiskers around the muzzle, a small dark eye, and a long thick tail that extends to the left beyond the frame. The dorsal and lateral surfaces of the body, tail, top of the head, and upper limbs are covered in overlapping rounded brown scales with darker centers and tan edges, interspersed with irregular patches of pale pinkish-white scales. The ventral surfaces, lower limbs, and face are covered in wrinkled, sparsely haired skin. Six bright pink, fleshy, feathery stalks with fine filamentous frills protrude from the neck and head region. The animal casts a soft shadow on the ground beneath its feet.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and narrow with a pointed snout, dark nostril at the tip, small round black eye with a lower eyelid, fine whiskers on the muzzle, wrinkled tan skin on the sides and underside, and small overlapping brown scales covering the top of the head and snout",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "a small dark circular ear opening with a slightly raised rim",
      "where": "on the side of the head behind and slightly below the eye, just in front of the pink gill stalks"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, muscular limbs with wrinkled gray-brown skin on the lower portions and overlapping brown scales on the upper portions near the body",
      "where": "two forelegs under the chest and shoulder, two hindlegs under the mid and rear body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad paws with thick textured skin and three prominent curved light-brown claws visible on each foot",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering toward the tip, covered dorsally and laterally with overlapping brown scales matching the body",
      "where": "extending from the rear left of the body, partially cropped by the left edge of the image"
    },
    {
      "part": "gills",
      "looks_like": "six bright pink fleshy stalks each bearing numerous fine feathery filaments along their length, giving a frilly appearance; three are visible on the near side of the neck behind the ear and three are visible protruding from the top of the head and neck on the far side",
      "where": "clustered around the neck and posterior head, behind the ear and on the dorsal midline of the head"
    },
    {
      "part": "scales",
      "looks_like": "overlapping rounded keratinous scales, mostly dark brown with lighter tan edges and darker centers, with visible growth lines; covering the back, sides, tail, top of head, and upper limbs",
      "where": "over the dorsal and lateral body, tail, top of head, and upper portions of all four limbs"
    },
    {
      "part": "markings",
      "looks_like": "irregular patches of pale pinkish-white scales with small dark speckles, interspersed among the brown scales",
      "where": "on the mid-back, lower flank, shoulder, and upper foreleg areas"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin",
    "axolotl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
